import java.util.*;
import java.lang.*;
import java.io.*;

class Codechef
{
    public static void main(String[] args) throws java.lang.Exception
    {
        // your code goes here
        Scanner in = new Scanner(System.in);
        int t, n, i;
        t = in.nextInt();
        while (t-- != 0)
        {
            n = in.nextInt();
            long arr[] = new long[3 * n];
            for (i = 0; i < 3 * n; i++)
                arr[i] = in.nextLong();
            Arrays.sort(arr);
            long s[] = new long[3 * n + 1];
            for (i = 0; i < 3 * n; i++)
                s[i + 1] = s[i] + arr[3 * n - 1 - i];
            long ans = 0;
            for (i = 0; i <= n; i++)
            {
                int l = 0, r = n - i;
                while (r - l > 2)
                {
                    int m1 = l + (r - l) / 3;
                    int m2 = r - (r - l) / 3;
                    long e1 = s[i + 2 * m1] + 3 * s[3 * n - 2 * i - m1];
                    long e2 = s[i + 2 * m2] + 3 * s[3 * n - 2 * i - m2];
                    if (e1 < e2)
                        l = m1;
                    else
                        r = m2;
                }
                for (int j = l; j <= r; j++)
                    ans = Math.max(ans, 2 * s[i] + s[i + 2 * j] + 3 *
                        s[3 * n - 2 * i - j]);
            }
            System.out.println(ans);
        }

    }
}
